-- Library in PostgreSQL: a seeded lookup table, a many-to-many link with a composite key,
-- enums, a domain, identity and serial keys, and loans whose dates follow each other.

CREATE TYPE book_language AS ENUM ('en', 'it', 'fr', 'de', 'es');
CREATE DOMAIN isbn13 AS char(13);

CREATE TABLE genres (
    code varchar(12) PRIMARY KEY,
    name text NOT NULL
);

INSERT INTO genres (code, name) VALUES
    ('fiction', 'Fiction'), ('history', 'History'), ('science', 'Science'), ('poetry', 'Poetry'), ('children', 'Children');

CREATE TABLE publishers (
    publisher_id serial PRIMARY KEY,
    name         varchar(80) NOT NULL UNIQUE,
    city         text
);

CREATE TABLE authors (
    author_id    integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name    text NOT NULL,
    birth_date   date,
    country_code char(2)
);

CREATE TABLE books (
    book_id      bigserial PRIMARY KEY,
    isbn         isbn13 NOT NULL UNIQUE,
    title        text NOT NULL,
    publisher_id integer NOT NULL REFERENCES publishers,
    genre_code   varchar(12) NOT NULL REFERENCES genres (code),
    language     book_language NOT NULL,
    published_on date NOT NULL,
    pages        integer NOT NULL CHECK (pages BETWEEN 10 AND 2000),
    price        numeric(8, 2) NOT NULL CHECK (price >= 0),
    keywords     text[]
);

CREATE TABLE book_authors (
    book_id      bigint NOT NULL REFERENCES books ON DELETE CASCADE,
    author_id    integer NOT NULL REFERENCES authors,
    author_order smallint NOT NULL CHECK (author_order BETWEEN 1 AND 5),
    PRIMARY KEY (book_id, author_id)
);

CREATE TABLE members (
    member_id  integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email      varchar(120) NOT NULL,
    first_name text NOT NULL,
    last_name  text NOT NULL,
    joined_on  date NOT NULL,
    active     boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX members_email ON members (email);

CREATE TABLE loans (
    loan_id     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    book_id     bigint NOT NULL,
    member_id   integer NOT NULL REFERENCES members,
    loaned_at   timestamp NOT NULL,
    due_at      timestamp NOT NULL,
    returned_at timestamp,
    CONSTRAINT ck_due CHECK (due_at > loaned_at),
    CONSTRAINT ck_returned CHECK (returned_at IS NULL OR returned_at >= loaned_at)
);

-- Later migrations.
ALTER TABLE loans ADD CONSTRAINT fk_loans_book FOREIGN KEY (book_id) REFERENCES books (book_id);
ALTER TABLE members ALTER COLUMN active DROP DEFAULT;
CREATE INDEX loans_open ON loans (member_id) WHERE returned_at IS NULL;

CREATE VIEW overdue_loans AS
    SELECT loan_id, member_id, due_at FROM loans WHERE returned_at IS NULL AND due_at < now();

COMMENT ON TABLE book_authors IS 'Who wrote which book, in credit order';
